declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/doctor_online_v580.php';$me=require_login();$uid=(int)$me['id'];$flash='';$error='';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){try{csrf_check();$a=(string)($_POST['action']??'');if($a==='family'){db()->prepare('INSERT INTO health_family_members_v580(tenant_id,owner_user_id,name,relation,date_of_birth,gender,created_at,updated_at) VALUES(?,?,?,?,?,?,NOW(),NOW())')->execute([do580_tid(),$uid,trim((string)$_POST['name']),trim((string)($_POST['relation']??''))?:null,($_POST['date_of_birth']??'')?:null,trim((string)($_POST['gender']??''))?:null]);$flash='Family profile added.';}elseif($a==='review'){$appt=do580_appointment((int)($_POST['appointment_id']??0));if(!$appt||(int)$appt['patient_user_id']!==$uid||$appt['status']!=='completed')throw new RuntimeException('Only completed appointments can be reviewed.');$rating=max(1,min(5,(int)($_POST['rating']??5)));db()->prepare("INSERT INTO health_reviews_v580(tenant_id,doctor_id,appointment_id,patient_user_id,rating,review,status,created_at) VALUES(?,?,?,?,?,?,'published',NOW()) ON DUPLICATE KEY UPDATE rating=VALUES(rating),review=VALUES(review),status='published'")->execute([do580_tid(),(int)$appt['doctor_id'],(int)$appt['id'],$uid,$rating,mb_substr(trim((string)($_POST['review']??'')),0,3000)]);do580_update_rating((int)$appt['doctor_id']);$flash='Review saved.';}}catch(Throwable $e){$error=$e->getMessage();}}$appointments=do580_my_appointments($uid);$sub=do580_patient_plan_active($uid);$family=[];$rx=[];try{$q=db()->prepare('SELECT * FROM health_family_members_v580 WHERE tenant_id=? AND owner_user_id=? ORDER BY name');$q->execute([do580_tid(),$uid]);$family=$q->fetchAll()?:[];$q=db()->prepare('SELECT r.*,d.display_name doctor_name,a.appointment_no FROM health_prescriptions_v580 r JOIN health_doctors_v580 d ON d.id=r.doctor_id JOIN health_appointments_v580 a ON a.id=r.appointment_id WHERE r.tenant_id=? AND r.patient_user_id=? ORDER BY r.id DESC LIMIT 50');$q->execute([do580_tid(),$uid]);$rx=$q->fetchAll()?:[];}catch(Throwable $e){}do580_public_header('My Health','Private patient dashboard for Doctor Online appointments and prescriptions.');
