<section class="do580-pagehead"><div class="do580-shell"><h1>My Health Dashboard</h1><p>Appointments, secure consultation rooms, prescriptions, family profiles and subscription status.</p></div></section><main class="do580-shell" style="padding:28px 0 56px"><?php if(!empty($_GET['booked'])):?><div class="do580-alert ok">Appointment request submitted successfully.</div><?php endif;?><?php if($flash):?><div class="do580-alert ok"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="do580-alert err"><?=e($error)?></div><?php endif;?><div class="do580-dashboard-grid"><div class="do580-stat"><small>Appointments</small><b><?=count($appointments)?></b></div><div class="do580-stat"><small>Prescriptions</small><b><?=count($rx)?></b></div><div class="do580-stat"><small>Family profiles</small><b><?=count($family)?></b></div><div class="do580-stat"><small>Active plan</small><b style="font-size:17px"><?=e($sub['plan_name']??'Pay per consult')?></b></div></div><section class="do580-panel" style="margin-top:18px"><div class="do580-head" style="margin-bottom:10px"><div><span>APPOINTMENTS</span><h2>My consultations</h2></div><a href="/find-doctor.php">Book another →</a></div><div style="overflow:auto"><table class="do580-table"><thead><tr><th>Appointment</th><th>Doctor</th><th>Mode</th><th>Time</th><th>Fee</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($appointments as $a):?><tr><td><b><?=e($a['appointment_no'])?></b><br><small><?=e($a['patient_name'])?></small></td><td><?=e($a['doctor_name'])?><br><small><?=e($a['specialty_name']?:'')?></small></td><td><?=e(str_replace('_',' ',$a['consultation_mode']))?></td><td><?=e(date('d M Y · h:i A',strtotime($a['scheduled_at'])))?></td><td><?=do580_money((float)$a['fee'])?><br><small><?=e($a['payment_status'])?></small></td><td><span class="do580-status <?=e($a['status'])?>"><?=e($a['status'])?></span></td><td><?php if(in_array($a['consultation_mode'],['video','audio','chat'],true)&&in_array($a['status'],['confirmed','waiting','in_progress','completed'],true)):?><a class="do580-btn secondary" href="/health-consultation.php?appointment=<?=(int)$a['id']?>"><?=$a['status']==='completed'?'View':'Enter Room'?></a><?php endif;?><?php if($a['status']==='completed'):?><details><summary>Review</summary><form method="post" class="do580-form" style="min-width:230px"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="review"><input type="hidden" name="appointment_id" value="<?=(int)$a['id']?>"><label>Rating<select name="rating"><option>5</option><option>4</option><option>3</option><option>2</option><option>1</option></select></label><label>Review<textarea name="review"></textarea></label><button class="do580-btn primary">Save</button></form></details><?php endif;?></td></tr><?php endforeach;?><?php if(!$appointments):?><tr><td colspan="7">No appointments yet.</td></tr><?php endif;?></tbody></table></div></section><div class="do580-main-grid"><section class="do580-panel"><h2>Digital prescriptions</h2><?php foreach($rx as $r):$med=do580_decode($r['medicines_json']);$tests=do580_decode($r['tests_json']);?><article style="padding:14px 0;border-bottom:1px solid #edf1f5"><b><?=e($r['doctor_name'])?> · <?=e($r['appointment_no'])?></b><p><?=e($r['diagnosis_note']?:'Consultation note')?></p><?php if($med):?><p><b>Medicines:</b> <?=e(implode(' · ',$med))?></p><?php endif;?><?php if($tests):?><p><b>Tests:</b> <?=e(implode(' · ',$tests))?></p><?php endif;?><p><?=nl2br(e($r['advice']?:''))?></p><small><?=e(date('d M Y',strtotime($r['created_at'])))?></small></article><?php endforeach;?><?php if(!$rx):?><p>No prescriptions yet.</p><?php endif;?></section><aside><section class="do580-panel"><h3>Family profiles</h3><?php foreach($family as $f):?><p><b><?=e($f['name'])?></b><br><small><?=e($f['relation']?:'Family member')?><?=!empty($f['date_of_birth'])?' · '.e($f['date_of_birth']):''?></small></p><?php endforeach;?><form method="post" class="do580-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="family"><label>Name<input name="name" required></label><label>Relation<input name="relation" placeholder="Child, parent, spouse"></label><div class="two"><label>Date of birth<input type="date" name="date_of_birth"></label><label>Gender<input name="gender"></label></div><button class="do580-btn secondary">Add Family Member</button></form></section><section class="do580-panel"><h3>Subscription</h3><?php if($sub):?><p><b><?=e($sub['plan_name'])?></b></p><p>Credits remaining: <?=max(0,(int)$sub['remaining_consults'])?></p><p>Ends: <?=e($sub['ends_at']?date('d M Y',strtotime($sub['ends_at'])):'No fixed end')?></p><?php else:?><p>No active patient subscription.</p><?php endif;?><a class="do580-btn secondary" href="/health-plans.php">View Plans</a></section></aside></div><div class="do580-clinical-note">Your Doctor Online dashboard contains private health-related information. Use a trusted device and sign out after use, especially on shared devices.</div></main><?php do580_public_footer(); ?>
